	}{
		{
			name: "duplicate LOG case variant",
			input: `{"currentTerm":1,
			  "LOG":[{"index":1,"term":null,"command":"a"}],
			  "log":[]}`,
			path: "log[0].term",
		},
		{
			name: "duplicate REQUESTS case variant",
			input: `{"currentTerm":1,
			  "REQUESTS":[{"term":null,"entries":[]}],
			  "requests":[]}`,
			path: "requests[0].term",
