172			a.appliedIndex = next
173		}
174	}
175	
176	// apply 把解析成功的操作作用到键值表，成功时返回空原因。各动作保留自己的
177	// 参数含义与失败原因：set 按原文写值，delete 删除（键不存在同样算成功），
178	// incr 按此前已生效的值累加。失败时键值表保持不变。
179	func (op kvOperation) apply(kv map[string]string) string {
180		switch {
181		case op.isDelete:
182			delete(kv, op.key)
183			return ""
184		case op.isIncr:
185			return op.applyIncr(kv)
186		default:
187			kv[op.key] = op.value
188			return ""
189		}
190	}
191	
192	// applyIncr 计算一次增量后的新值并写回：键不存在时当前值按 0 处理（并因此
193	// 创建该键）；当前值必须是有符号 64 位十进制整数，相加结果也不得超出该范围。
194	// 成功时写回不带前导零的规范十进制形式（零统一为 "0"），增量为 0 同样写回
195	// 规范形式；失败时返回具体原因，键值表保持不变。
196	func (op kvOperation) applyIncr(kv map[string]string) string {
197		current := int64(0)
198		if existing, ok := kv[op.key]; ok {
199			value, valid := parseKVInt(existing)
200			if !valid {
201				return ApplyReasonIncrBadCurrent
202			}
203			current = value
204		}
205		sum, ok := addKVInt(current, op.delta)
206		if !ok {
207			return ApplyReasonIncrOverflow
208		}
209		kv[op.key] = strconv.FormatInt(sum, 10)
210		return ""
211	}
