// unmarshalLastWinsEntries 是 unmarshalLastWinsArray 的日志条目版本：元素经
// replicateInputEntry 解码（command 重复出现按最后一次定值），再整体转换回
// 库类型切片，调用方与输出层看到的仍只有 mevwatch.LogEntry。
func unmarshalLastWinsEntries(data []byte, dst *[]mevwatch.LogEntry) error {
	var next []replicateInputEntry
	if err := json.Unmarshal(data, &next); err != nil {
		return err
	}
	if next == nil {
		*dst = nil
		return nil
	}
	entries := make([]mevwatch.LogEntry, len(next))
	for i := range next {
		entries[i] = mevwatch.LogEntry(next[i])
	}
	*dst = entries
	return nil
}
