// replicateInputEntry 是读取阶段的日志条目：以库类型 mevwatch.LogEntry 为底层
// 类型另行定义，只挂载输入特有的 command 解码规则。公开说明要求同一对象里重复
// 出现的字段由输入中的最后一次出现决定内容，而 encoding/json 把 null 解进
// string 字段时保持原值不变，{"command":"set count=7","command":null} 会错误
// 留下前面的写入。这里改为显式扫描 command 的每一次出现（只改变大小写的写法
// 同样命中）：每次出现必须是字符串或 null——数字、布尔值、对象、数组都是输入
// 类型错误，后面的合法字符串不能掩盖；最后一次出现为字符串时按原文保留，为
// null（或从未出现）时为空字符串。index/term 与未知字段沿用普通结构体解码，
// 重复数值键后者生效、类型错误保留既有格式。
type replicateInputEntry mevwatch.LogEntry

// entryScalarFields 是条目对象里除 command 外的已识别字段：command 由
// lastCommandValue 单独按“最后一次出现定值”处理，不进入这份结构体，避免
// 非法类型的前序出现被静默丢弃。
type entryScalarFields struct {
	Index int `json:"index"`
	Term  int `json:"term"`
}

