// runReplicateRaw 执行一次 replicate，断言正常完成（退出码 0、stderr 为空），
// 同时返回解码后的结果与原始输出文本：conflict 键“完全不出现”与“出现但为
// null”只能通过原始文本区分。
func runReplicateRaw(t *testing.T, input string) (mevwatch.ReplicateOutput, string) {
	t.Helper()
